try{(function(){"use strict";if(!window.MC||!MC.reg||MC.tests.panic)return;var a=[["Nahi","No"],["Haan","Yes"]],e="#16a34a",b="#65a30d",x="#d97706",j="#ea580c",h="#dc2626",g=["Ye hamari apni checklist hai, validated test nahi. Iska koi official cut-off nahi, ye sirf batati hai ki kitni baatein aap par lagu hui.","This is our own checklist, not a validated test. It has no official cut-off; it only shows how many points apply to you."];function T(r,u,i,k,c,n,y,m){MC.reg({id:r,name:u,sub:i,max:c.length,opts:a,intro:k,items:c,calc:function(M){var f=0,K;for(K=0;K<c.length;K++)f+=M[K]||0;var J=f>=n;return{s:f,b:J?[0,c.length,"Several points apply",j,2]:f>0?[0,c.length,"Few points apply",b,1]:[0,c.length,"No points apply",e,0],lines:[g],adv:J?m:y}}})}var o=[["Hriday tez dhadakna","Heart racing, pounding or skipping"],["Saans phoolna","Shortness of breath"],["Seene me dard ya dabav","Chest pain or pressure"],["Pasina aana","Sweating"],["Dam ghutne jaisa lagna","Feeling as if you were choking"],["Garmi ki lahar ya kampkampi","Hot flashes or chills"],["Ji michlana ya pet kharab","Nausea or upset stomach"],["Chakkar ya behoshi jaisa lagna","Feeling dizzy, unsteady or faint"],["Sunn hona ya jhunjhuni","Tingling or numbness"],["Haath-pair kaanpna","Trembling or shaking"],["Darr ki mar jaunga/jaungi","Being afraid you were dying"]];MC.reg({id:"panic",name:["Panic attack screen","Panic attack screen"],sub:["Achanak tez ghabrahat ke daure, 15 sawal","Sudden surges of fear, 15 questions"],max:11,opts:a,intro:["Agar pehle sawal ka jawab Nahi hai, to baaki sawalon me Nahi chunein. Last bure daure ke baare me jawab dein.","If the first answer is No, answer No to the rest. Answer the symptom questions about your last bad attack."],items:[["Pichhle 4 hafton me kya kabhi achanak tez darr ya panic ka daura pada?","In the last 4 weeks, have you had an anxiety attack: suddenly feeling fear or panic?"],["Kya aisa pehle bhi hua hai?","Has this ever happened before?"],["Kya kuch daure bina wajah ke, achanak aate hain, jahan aap ghabrane ki ummeed nahi karte?","Do some of these attacks come out of the blue, where you did not expect to be nervous?"],["Kya ye daure aapko bahut pareshan karte hain, ya agla daura padne ka darr rehta hai?","Do the attacks bother you a lot, or do you worry about having another one?"]].concat(o.map(function(r){return["Last bure daure me: "+r[0],"During your last bad attack: "+r[1]]})),calc:function(r){var u=r[0]&&r[1]&&r[2]&&r[3],i=0,k;for(k=4;k<15;k++)i+=r[k]||0;var c=u&&i>=4;return{s:i,b:c?[0,11,"Positive: panic pattern",j,2]:r[0]?[0,11,"Some panic-like episodes",x,1]:[0,11,"No panic pattern",e,0],lines:[["Positive screen ke liye: pehle 4 sawalon me Haan aur 11 lakshanon me se 4 ya zyada.","Positive screen needs: Yes to the first 4 questions and 4 or more of the 11 symptoms."]],adv:c?["Ye panic disorder ke liye positive screen hai, diagnosis nahi. Pehli baar seene ka dard ya saans ki dikkat ho to pehle doctor se dil aur thyroid jaisi jaanch karayein. Phir psychiatrist ya psychologist se milein; CBT aur dawai dono kaam karte hain.","This is a positive screen for panic disorder, not a diagnosis. If chest pain or breathlessness is new, first see a doctor to rule out heart or thyroid causes. Then see a psychiatrist or psychologist; CBT and medicines both work."]:["Abhi panic pattern poora nahi dikhta. Agar daure baar-baar aate hain to doctor se baat karein.","A full panic pattern is not showing. If attacks keep coming, talk to a doctor."]}}}),MC.reg({id:"hrs",name:["Hoarding screen","Hoarding screen"],sub:["Cheezein jama karna, 5 sawal","Hoarding and clutter, 5 questions"],max:40,opts:[["Koi dikkat nahi","No problem"],["Halki","Mild"],["Madhyam","Moderate"],["Gambhir","Severe"],["Behad gambhir","Extreme"]],intro:["Ghar me cheezein jama hone ke baare me, abhi ke samay ke hisaab se jawab dein.","Think about your current situation with clutter and possessions."],items:[["Cheezon ki bheed ki wajah se ghar ke kamre istemal karna kitna mushkil hai?","Because of clutter or the number of possessions, how hard is it to use the rooms in your home?"],["Aam cheezein (jo log phenk dete hain) phenkna ya de dena kitna mushkil hai?","How hard is it to discard ordinary things that other people would get rid of?"],["Muft cheezein ikatthi karne ya zaroorat se zyada kharidne ki aadat kitni badi dikkat hai?","How big a problem is collecting free things or buying more than you need or can afford?"],["In sab ki wajah se aapko kitni takleef ya pareshani hoti hai?","How much distress do these things cause you?"],["Inki wajah se kaam, parivaar, dosti, paise ya sehat me kitni rukawat aati hai?","How much do these interfere with work, family, social life, money or health?"]],calc:function(r){var u=function(y){return(r[y]||0)*2},i=0,k;for(k=0;k<5;k++)i+=u(k);var c=u(0)>=4&&u(1)>=4&&(u(3)>=4||u(4)>=4),n=i>=14;return{s:i,b:n?[0,40,"At or above cut-off",j,2]:[0,40,"Below cut-off",e,0],lines:[["Cut-off 14 (0 se 40). Alag se: clutter aur phenkne ki dikkat dono madhyam ya zyada, aur takleef ya rukawat bhi madhyam ya zyada ho to clinically significant mana jata hai: "+(c?"haan.":"nahi."),"Cut-off 14 (0 to 40). Clinically significant hoarding also needs clutter and difficulty discarding both moderate or higher, plus moderate distress or interference: "+(c?"met.":"not met.")]],adv:n?["Score hoarding disorder ke liye cut-off par ya upar hai. Ye diagnosis nahi hai. Psychologist ya psychiatrist se milein; CBT kaafi madad karti hai. Jabardasti safai se faayda nahi hota, dheere-dheere saath chalein.","The score is at or above the cut-off for hoarding disorder. It is not a diagnosis. See a psychologist or psychiatrist; CBT helps. Forced clean-outs do not work, so go gradually."]:["Cut-off se neeche hai. Agar ghar me jagah ya rishton par asar pad raha hai to professional se baat karein.","Below the cut-off. If clutter affects space or relationships, consider talking to a professional."]}}}),T("bdd",["Appearance worry checklist","Appearance worry checklist"],["Shakal ya sharir ki chinta, 7 sawal","Worry about appearance, 7 questions"],["Pichhle 1 mahine ke baare me jawab dein.","Answer about the past month."],[["Kya aap apne rang-roop ya sharir ke kisi hisse ki kami ke baare me bahut sochte hain, jo doosron ko mushkil se dikhti hai ya nahi dikhti?","Do you think a lot about a flaw in your appearance that others barely notice or cannot see?"],["Kya ye vichaar roz 1 ghante se zyada lete hain?","Do these thoughts take more than an hour a day?"],["Kya aap baar-baar sheesha dekhte hain, ya bilkul nahi dekhte?","Do you check mirrors again and again, or avoid them completely?"],["Kya aap kami chhupane (makeup, kapde, angle) me bahut samay lagate hain?","Do you spend a lot of time hiding the flaw (makeup, clothes, angles)?"],["Kya aap doosron se tulna ya baar-baar bharosa maangte hain?","Do you often compare yourself or ask others for reassurance?"],["Kya shakal ki chinta se aap logon se milna ya bahar jaana taalte hain?","Do you avoid people or going out because of this worry?"],["Kya isse aapko bahut takleef hoti hai, ya kaam, padhai ya rishton me dikkat aati hai?","Does this cause you strong distress, or trouble with work, study or relationships?"]],4,["Abhi zyada points nahi lagte. Agar chinta badhe to professional se baat karein.","Not many points apply now. Talk to a professional if the worry grows."],["Kai points lagte hain. Ye body dysmorphic disorder jaisa ho sakta hai, jisme shakal ki chinta asli kami se kahin badi hoti hai. Ye diagnosis nahi hai. Psychologist ya psychiatrist se milein; cosmetic surgery se pehle zaroor baat karein, kyunki isse aksar rahat nahi milti.","Several points apply. This can look like body dysmorphic disorder, where worry about appearance is far bigger than any visible flaw. It is not a diagnosis. See a psychologist or psychiatrist, and talk to them before any cosmetic procedure, because it often does not bring relief."]),T("tricho",["Hair-pulling checklist","Hair-pulling checklist"],["Baal noochna, 7 sawal","Pulling out hair, 7 questions"],["Pichhle 1 mahine ke baare me jawab dein.","Answer about the past month."],[["Kya aap apne baal (sir, bhaunh, palken ya kahin aur ke) kheenchkar tod dete hain?","Do you pull out your own hair (scalp, eyebrows, lashes or elsewhere)?"],["Kya isse baalon ka patla hona ya ganjapan dikhta hai?","Has this caused visible thinning or bald patches?"],["Kya baal noochne se pehle tanav ya bechaini badhti hai, aur noochne ke baad rahat milti hai?","Do you feel rising tension before pulling and relief afterwards?"],["Kya aap kabhi bina dhyan diye (TV, padhte waqt) noochte rehte hain?","Do you sometimes pull without noticing, for example while watching TV or reading?"],["Kya aapne ise rokne ki koshish ki par nahi ruk paye?","Have you tried to stop and not managed to?"],["Kya aap ise chhupane ke liye topi, makeup ya bahar jaana taalte hain?","Do you hide it with hats or makeup, or avoid going out?"],["Kya isse aapko sharm, takleef ya rozmarra me dikkat hoti hai?","Does it cause shame, distress or trouble in daily life?"]],4,["Zyada points nahi lagte. Aadat badhe to professional se baat karein.","Not many points apply. Talk to a professional if the habit grows."],["Kai points lagte hain. Ye trichotillomania jaisa ho sakta hai. Ye diagnosis nahi hai. Psychologist se milein; habit reversal training (HRT) sabse madadgar ilaaj hai. Sharm na karein, ye bahut logon me hota hai.","Several points apply. This can look like trichotillomania. It is not a diagnosis. See a psychologist; habit reversal training (HRT) is the most helpful treatment. There is no need for shame; it is common."]),T("skinp",["Skin-picking checklist","Skin-picking checklist"],["Skin nochna ya khurchna, 7 sawal","Picking at skin, 7 questions"],["Pichhle 1 mahine ke baare me jawab dein.","Answer about the past month."],[["Kya aap baar-baar apni skin (muhase, daane, khurand) nochte ya khurchte hain?","Do you often pick at your skin (pimples, scabs, bumps)?"],["Kya isse ghaav, nishaan ya infection hue hain?","Has this caused sores, scars or infections?"],["Kya aap ek baar shuru karke ghanton tak noch sakte hain?","Can you start and keep picking for long periods?"],["Kya aap tanav, bechaini ya bore hone par zyada nochte hain?","Do you pick more when stressed, anxious or bored?"],["Kya aapne rokne ki koshish ki par nahi ruk paye?","Have you tried to stop and not managed to?"],["Kya aap nishaan chhupane ke liye kapde ya makeup ka sahara lete hain, ya logon se bachte hain?","Do you hide marks with clothes or makeup, or avoid people?"],["Kya isse aapko sharm, takleef ya rozmarra me dikkat hoti hai?","Does it cause shame, distress or trouble in daily life?"]],4,["Zyada points nahi lagte. Skin ko saaf rakhein aur dhyan dein agar aadat badhe.","Not many points apply. Keep the skin clean and watch if the habit grows."],["Kai points lagte hain. Ye excoriation (skin-picking) disorder jaisa ho sakta hai. Ye diagnosis nahi hai. Psychologist se milein; habit reversal training madad karti hai. Gehre ghaav ya infection ho to skin doctor ko dikhayein.","Several points apply. This can look like excoriation (skin-picking) disorder. It is not a diagnosis. See a psychologist; habit reversal training helps. See a skin doctor for deep wounds or infection."]),T("phobia",["Specific fear checklist","Specific fear checklist"],["Kisi khaas cheez se bahut darr, 7 sawal","Intense fear of one thing or situation, 7 questions"],["Kisi ek khaas cheez ya sthiti ke baare me socho: jaise oonchai, jaanwar, injection ya khoon, udaan, band jagah, andhera.","Think about one specific thing or situation: for example heights, animals, injections or blood, flying, enclosed spaces, darkness."],[["Kya us cheez se aapko bahut tez darr lagta hai?","Does that thing or situation cause you intense fear?"],["Kya wo cheez saamne aate hi lagbhag har baar darr turant aata hai?","Does fear come almost every time, right away?"],["Kya aap use taalte hain, ya bahut takleef me sahte hain?","Do you avoid it, or endure it with great distress?"],["Kya aapka darr asli khatre se kahin zyada hai?","Is the fear much bigger than the real danger?"],["Kya ye darr 6 mahine ya zyada se hai?","Has this fear lasted 6 months or more?"],["Kya isse aapka kaam, safar, sehat ya rozmarra badla hai?","Has it changed your work, travel, health care or daily life?"],["Kya sirf is ek cheez ke bahar aapko aisa darr nahi lagta?","Is this fear mostly limited to this one thing or situation?"]],5,["Abhi zyada points nahi lagte. Halka darr aam hai.","Not many points apply. Mild fears are common."],["Kai points lagte hain. Ye specific phobia jaisa ho sakta hai. Ye diagnosis nahi hai. Psychologist se milein; dheere-dheere exposure therapy sabse prabhavi hai aur aksar kuch hi sessions me kaam karti hai.","Several points apply. This can look like a specific phobia. It is not a diagnosis. See a psychologist; gradual exposure therapy is the most effective and often works in a few sessions."]),T("agora",["Fear of going out checklist","Fear of going out checklist"],["Bahar jaane ya bheed se darr, 7 sawal","Fear of going out or crowds, 7 questions"],["Pichhle 6 mahine ke baare me jawab dein.","Answer about the past 6 months."],[["Kya bus, train ya metro me safar karne se aapko bahut darr lagta hai?","Do you feel intense fear using buses, trains or the metro?"],["Kya khuli jagah (maidan, bridge, bada bazaar) me aapko darr lagta hai?","Do open spaces (fields, bridges, big markets) frighten you?"],["Kya band jagah (lift, cinema, dukaan) me aapko darr lagta hai?","Do enclosed places (lifts, cinemas, shops) frighten you?"],["Kya line me khade hone ya bheed me hone se aapko darr lagta hai?","Do queues or crowds frighten you?"],["Kya akele ghar se bahar jaane se aapko darr lagta hai?","Do you fear being outside the home alone?"],["Kya aapko lagta hai ki wahan se nikalna mushkil hoga ya madad nahi milegi, aur isliye aap bachte hain ya kisi ko saath le jaate hain?","Do you fear escape or help would be hard to get, so you avoid these or need someone with you?"],["Kya isse aapka kaam, padhai ya rozmarra badla hai?","Has this changed your work, study or daily life?"]],4,["Zyada points nahi lagte. Agar bahar jaane ka darr badhe to professional se baat karein.","Not many points apply. Talk to a professional if the fear of going out grows."],["Kai points lagte hain. Ye agoraphobia jaisa ho sakta hai, jo aksar panic ke daure ke baad shuru hota hai. Ye diagnosis nahi hai. Psychologist ya psychiatrist se milein; dheere-dheere bahar nikalne wali exposure therapy kaafi madad karti hai.","Several points apply. This can look like agoraphobia, which often begins after panic attacks. It is not a diagnosis. See a psychologist or psychiatrist; gradual exposure therapy helps a great deal."]),T("iad",["Health worry checklist","Health worry checklist"],["Badi bimari ka darr, 7 sawal","Fear of having a serious illness, 7 questions"],["Pichhle 6 mahine ke baare me jawab dein.","Answer about the past 6 months."],[["Kya aap bahut chinta karte hain ki aapko koi gambhir bimari hai ya ho jayegi?","Do you worry a lot that you have, or will get, a serious illness?"],["Kya doctor ki jaanch normal aane par bhi chinta kuch hi der me wapas aa jaati hai?","Does the worry return soon even after normal medical tests?"],["Kya aap baar-baar apna sharir check karte hain ya internet par lakshan khojte hain?","Do you keep checking your body or searching symptoms online?"],["Kya aap doctor ya hospital se bachte hain, kyunki bura nateeja nikalne ka darr hai?","Do you avoid doctors or hospitals for fear of bad news?"],["Kya aapke sharir me lakshan bahut halke hain ya nahi hain, phir bhi chinta badi hai?","Are your physical symptoms mild or absent, yet the worry is large?"],["Kya ye chinta 6 mahine ya zyada se hai?","Has this worry lasted 6 months or more?"],["Kya isse aapka kaam, rishte ya neend badle hain?","Has it affected your work, relationships or sleep?"]],4,["Zyada points nahi lagte. Sehat ki chinta thodi aam hai.","Not many points apply. Some health worry is common."],["Kai points lagte hain. Ye illness anxiety jaisa ho sakta hai. Ye diagnosis nahi hai. Pehle ek doctor se ek baar poori jaanch karayein, phir psychologist se milein; CBT kaafi madad karti hai. Baar-baar jaanch ya internet search chinta ko badhate hain.","Several points apply. This can look like illness anxiety. It is not a diagnosis. Have one full check-up with a doctor, then see a psychologist; CBT helps a great deal. Repeated checking and online searches keep the worry going."]);var t=["self","18+ saal","Ages 18+","Aap khud apne baare me","You, about yourself"];["panic","hrs","bdd","tricho","skinp","phobia","agora","iad"].forEach(function(r){MC.who[r]=t,MC.names[r]=MC.tests[r].name[1]});function C(r,u){var i=MC.tabs.a[r];u.forEach(function(k){i.ids.indexOf(k)<0&&i.ids.push(k)})}C(1,["panic","agora","phobia","iad"]),C(4,["hrs","bdd","tricho","skinp"]);var s={},p=[];["a","c"].forEach(function(r){MC.tabs[r].forEach(function(u){var i=u.ids.filter(function(k){return s[k]?!1:(s[k]=1,!0)});i.length&&p.push({t:u.t,ids:i})})}),MC.groups=p})()}catch(a){setTimeout(function(){throw a})}try{(function(){"use strict";if(!window.MC||!MC.reg||MC.tests.phq15)return;var a=[["Nahi","No"],["Haan","Yes"]],e="#16a34a",b="#65a30d",x="#d97706",j="#ea580c",h="#dc2626",g=window.NT_RM={sdq:1,mchat:1,mdq:1,vand:1,ybocs:1,scared:1};Object.keys(g).forEach(function(y){delete MC.tests[y]});var T=MC.start;MC.start=function(y){if(MC.tests[y])return T.apply(this,arguments)};var o=["Ye hamari apni checklist hai, validated test nahi. Iska koi official cut-off nahi, ye sirf batati hai ki kitni baatein aap par lagu hui.","This is our own checklist, not a validated test. It has no official cut-off; it only shows how many points apply to you."];function t(y,m,M,f,K,J,ta,P){MC.reg({id:y,name:[m,m],sub:M,max:K.length,opts:a,intro:f,items:K,calc:function(U){var ra=0,q;for(q=0;q<K.length;q++)ra+=U[q]||0;var Z=ra>=J;return{s:ra,b:Z?[0,K.length,"Several points apply",j,2]:ra>0?[0,K.length,"Few points apply",b,1]:[0,K.length,"No points apply",e,0],lines:[o],adv:Z?P:ta}}})}var C=[["Pet dard","Stomach pain"],["Peeth dard","Back pain"],["Haath, pair ya jodon me dard","Pain in arms, legs or joints"],["Mahavari me dard ya dikkat (mahilaon ke liye; lagu na ho to Pareshan nahi kiya)","Menstrual cramps or other period problems (women; if not applicable, choose Not bothered)"],["Sambandh banate waqt dard ya dikkat (lagu na ho to Pareshan nahi kiya)","Pain or problems during sexual intercourse (if not applicable, choose Not bothered)"],["Sir dard","Headaches"],["Seene me dard","Chest pain"],["Chakkar aana","Dizziness"],["Behoshi ke daure","Fainting spells"],["Dil tez dhadakna ya daudna","Feeling your heart pound or race"],["Saans phoolna","Shortness of breath"],["Kabz ya dast","Constipation, loose bowels or diarrhea"],["Ji michlana, gas ya badhazmi","Nausea, gas or indigestion"],["Thakaan ya energy kam hona","Feeling tired or having low energy"],["Neend ki dikkat","Trouble sleeping"]];MC.reg({id:"phq15",name:["Somatic symptoms (body complaints)","Somatic symptoms (body complaints)"],sub:["Sharir ke kai lakshan, 15 sawal","Many physical complaints, 15 questions"],max:30,opts:[["Pareshan nahi kiya","Not bothered at all"],["Thoda pareshan kiya","Bothered a little"],["Kaafi pareshan kiya","Bothered a lot"]],intro:["Pichhle 4 hafton me, ye lakshan aapko kitna pareshan karte rahe?","Over the last 4 weeks, how much have these problems bothered you?"],items:C,calc:function(y){var m=0,M;for(M=0;M<15;M++)m+=y[M]||0;var f=m<5?[0,30,"Minimal",e,0]:m<10?[0,30,"Low",b,1]:m<15?[0,30,"Medium",x,2]:[0,30,"High",j,3];return{s:m,b:f,lines:[["Cut-off: 5 halka, 10 madhyam, 15 zyada (0 se 30).","Cut-offs: 5 low, 10 medium, 15 high (0 to 30)."]],adv:m>=10?["Sharir ke lakshan kaafi zyada pareshan kar rahe hain. Pehle doctor se jaanch karayein taaki koi sharirik kaaran chhoot na jaye. Agar jaanch normal ho par chinta ya takleef bani rahe, to psychiatrist ya psychologist se milein; ye lakshan tanav aur anxiety se bhi badhte hain. Ye diagnosis nahi hai.","These body symptoms are bothering you a lot. First see a doctor so no physical cause is missed. If tests are normal but worry or distress continues, see a psychiatrist or psychologist; stress and anxiety can raise these symptoms. This is not a diagnosis."]:["Abhi lakshan kam se madhyam hain. Neend, khana aur activity theek rakhein; badhe to doctor se milein.","Symptoms are low to minimal now. Keep sleep, food and activity steady; see a doctor if they grow."]}}}),t("cptsd","Complex PTSD",["Lambe ya baar-baar bure anubhav ke baad, 8 sawal","After long or repeated bad experiences, 8 questions"],["Un bure anubhavon ke baare me socho jo lambe samay ya baar-baar hue (jaise bachpan me ya ghar me). Pichhle 1 mahine ke baare me jawab dein.","Think about bad experiences that went on for a long time or happened repeatedly, for example in childhood or at home. Answer about the past month."],[["Kya us anubhav ki yaadein, sapne ya flashback ab bhi aate hain?","Do memories, nightmares or flashbacks of it still come back?"],["Kya aap uski yaad dilane wali cheezon, logon ya jagahon se bachte hain?","Do you avoid reminders such as people, places or conversations?"],["Kya aap hamesha chaukanne rehte hain, ya zara si awaaz par chaunk jaate hain?","Are you always on guard, or easily startled?"],["Kya bhavnayein achanak bahut tez ho jaati hain, ya kuch mehsoos hi nahi hota, aur sambhalna mushkil hai?","Do emotions suddenly become very intense, or numb, and are hard to manage?"],["Kya aap khud ko bekaar, haara hua ya sharminda samajhte hain?","Do you see yourself as worthless, defeated or ashamed?"],["Kya doosron ke kareeb aana ya rishte banaye rakhna mushkil lagta hai?","Is it hard to feel close to others or keep relationships?"],["Kya ye pareshaniyan aapke kaam, padhai ya rishton me rukawat banti hain?","Do these troubles get in the way of work, study or relationships?"],["Kya wo anubhav kai mahine ya saal chale, ya baar-baar hue?","Did the experience go on for months or years, or happen again and again?"]],5,["Abhi zyada points nahi lagte. Agar yaadein pareshan karein to professional se baat karein.","Not many points apply now. Talk to a professional if memories keep troubling you."],["Kai points lagte hain. Ye complex PTSD jaisa ho sakta hai, jo lambe samay ke bure anubhavon ke baad hota hai. Ye diagnosis nahi hai. Trauma ko samajhne wale psychologist ya psychiatrist se milein; ilaaj dheere-dheere surakshit tareeke se hota hai. Agar khud ko nuksan ke vichaar aayein to Tele-MANAS 14416 par call karein.","Several points apply. This can look like complex PTSD, which follows long-lasting bad experiences. It is not a diagnosis. See a psychologist or psychiatrist who understands trauma; treatment is gradual and safe. If you have thoughts of harming yourself, call Tele-MANAS 14416."]),t("grief","Prolonged grief",["Apne ko khone ke baad lamba dukh, 10 sawal","Long-lasting grief after a loss, 10 questions"],["Kisi apne ki maut ko kam se kam 6 mahine hue hon to jawab dein. Pichhle 1 mahine ke baare me socho.","Answer if someone close died at least 6 months ago. Think about the past month."],[["Kya aap use bahut yaad karte hain ya milne ki tadap rehti hai, lagbhag roz?","Do you long for the person or yearn for them almost every day?"],["Kya aapka dhyan lagbhag poori tarah unhi ke vichaaron me rehta hai?","Are you almost completely preoccupied with thoughts of them?"],["Kya ab bhi yakeen karna mushkil lagta hai ki wo chale gaye?","Is it still hard to believe they are gone?"],["Kya aapko lagta hai ki aapka ek hissa unke saath chala gaya?","Do you feel a part of you died with them?"],["Kya aap unki yaad dilane wali cheezon se bachte hain?","Do you avoid reminders of them?"],["Kya aapko bahut gehra bhavnatmak dard hota hai?","Do you feel intense emotional pain?"],["Kya dosti, kaam ya purani cheezon me wapas judna mushkil lagta hai?","Is it hard to get back into friendships, work or things you used to do?"],["Kya aap sunn ya sanvedanheen mehsoos karte hain?","Do you feel emotionally numb?"],["Kya zindagi bekaar ya khaali lagti hai?","Does life feel meaningless or empty?"],["Kya isse aapka kaam, padhai ya rozmarra bahut prabhavit hua hai?","Has it badly affected your work, study or daily life?"]],6,["Dukh maut ke baad aam hai. Waqt aur apno ka saath madad karta hai. Agar dukh bahut lamba chale to baat karein.","Grief is normal after a loss. Time and the support of loved ones help. Talk to someone if it stays very heavy."],["Kai points lagte hain. Ye prolonged grief jaisa ho sakta hai, jisme dukh 6 mahine ke baad bhi bahut gehra rehta hai. Ye diagnosis nahi hai. Psychologist se milein; grief-focused therapy madad karti hai. Agar jeene ka mann na kare to abhi Tele-MANAS 14416 par call karein.","Several points apply. This can look like prolonged grief, where grief stays very intense after 6 months. It is not a diagnosis. See a psychologist; grief-focused therapy helps. If you feel you do not want to live, call Tele-MANAS 14416 now."]),t("adj","Adjustment disorder",["Badi tanav wali ghatna ke baad pareshani, 7 sawal","Distress after a major life stress, 7 questions"],["Pichhle 3 mahine me hui kisi badi cheez ke baare me socho: naukri jaana, breakup, bimari, shift hona, nuksan.","Think about a major event in the past 3 months: job loss, breakup, illness, moving, a loss."],[["Kya pichhle 3 mahine me koi badi tanav wali ghatna hui?","Did a major stressful event happen in the past 3 months?"],["Kya uske baad se aap zyada chintit, udaas ya chidchide rehte hain?","Since then, do you feel more worried, low or irritable?"],["Kya aap baar-baar usi baat ke baare me sochte rehte hain?","Do you keep thinking about the same thing over and over?"],["Kya aapki pareshani us ghatna ke hisaab se zyada lagti hai?","Does your distress seem bigger than expected for the event?"],["Kya isse kaam, padhai ya rishton me dikkat aa rahi hai?","Is it causing trouble in work, study or relationships?"],["Kya neend ya bhookh badli hai?","Have your sleep or appetite changed?"],["Kya ye pareshani ghatna se pehle nahi thi?","Was this distress not there before the event?"]],4,["Zyada points nahi lagte. Tanav ke baad halki pareshani aam hai.","Not many points apply. Mild distress after stress is common."],["Kai points lagte hain. Ye adjustment disorder jaisa ho sakta hai. Ye diagnosis nahi hai. Kisi apne se baat karein aur psychologist se milein; kuch hafton ki therapy aksar kaafi hoti hai. Agar jeene ka mann na kare to Tele-MANAS 14416.","Several points apply. This can look like adjustment disorder. It is not a diagnosis. Talk to someone close and see a psychologist; a few weeks of therapy is often enough. If you feel you do not want to live, call Tele-MANAS 14416."]),t("diss","Dissociation (depersonalization, amnesia)",["Khud ya duniya nakli lagna, yaad ke gap, 8 sawal","Feeling unreal, or memory gaps, 8 questions"],["Pichhle 1 mahine ke baare me jawab dein, nashe ya dawai ke asar ke bina.","Answer about the past month, not counting the effects of drugs, alcohol or medicines."],[["Kya aapko lagta hai ki aap apne sharir se bahar hain, jaise khud ko bahar se dekh rahe hon?","Do you feel outside your body, as if watching yourself from outside?"],["Kya aapko apne vichaar ya bhavnayein apne nahi lagte?","Do your thoughts or feelings feel like they are not yours?"],["Kya aas-paas ki duniya nakli, dhundhli ya sapne jaisi lagti hai?","Does the world around you feel unreal, foggy or dreamlike?"],["Kya aapko ghanton ya dinon ki baatein yaad nahi rehti?","Are there hours or days you cannot remember?"],["Kya aap kisi jagah pahunch kar bhool jaate hain ki kaise aaye?","Do you find yourself somewhere without remembering how you got there?"],["Kya aapko zaroori roz ki baatein bhi yaad nahi rehti jo koi bhi yaad rakhta?","Do you forget important everyday things most people would remember?"],["Kya isse aapko darr ya takleef hoti hai?","Does this scare or distress you?"],["Kya ye baar-baar ya 1 mahine se zyada hota hai?","Does it happen often, or for more than a month?"]],4,["Zyada points nahi lagte. Thakaan ya tanav me kabhi-kabhi aisa lagna aam hai.","Not many points apply. Feeling this way now and then under stress or tiredness is common."],["Kai points lagte hain. Ye dissociation jaisa ho sakta hai, jo aksar tanav ya bure anubhavon se judta hai. Ye diagnosis nahi hai. Pehle doctor se milein taaki neend, daure (epilepsy) ya nashe jaise kaaran dekhe jayein. Phir psychologist ya psychiatrist se milein.","Several points apply. This can look like dissociation, which is often linked to stress or bad experiences. It is not a diagnosis. First see a doctor to rule out causes such as sleep problems, seizures or substances. Then see a psychologist or psychiatrist."]);var s=["self","18+ saal","Ages 18+","Aap khud apne baare me","You, about yourself"];["phq15","cptsd","grief","adj","diss"].forEach(function(y){MC.who[y]=s});var p={phq9:"Depression",gad7:"Generalized anxiety",sr:"Suicide risk (safety check)",pcl5:"PTSD",ocir:"OCD",docs:"OCD (4 types)",aq10:"Autism (adult)",scq:"Autism (child)",psc17:"Child emotional and behaviour problems",phqa:"Teen depression",msi:"Borderline personality",spin:"Social anxiety",sadc:"Social anxiety (child and teen)",asrm:"Mania",pqb:"Psychosis risk",panic:"Panic disorder",hrs:"Hoarding disorder",bdd:"Body dysmorphic disorder",tricho:"Trichotillomania (hair-pulling)",skinp:"Skin-picking disorder",phobia:"Specific phobia",agora:"Agoraphobia",iad:"Illness anxiety"},r={sr:["Jaan ke khatre ka safety check, 5 haan/nahi sawal","Safety check for suicide risk, 5 yes/no questions"],asrm:["Mania ka check, 5 sawal","Mania check, 5 questions"],phqa:["Kishoron me depression, 11 se 17 saal","Teen depression, ages 11 to 17"],scq:["Baat-cheet aur vyavhar ka checklist, 16 sawal, 4+ saal","Communication and behaviour checklist, 16 questions, ages 4+"]},u=[[/Ye asli SCQ nahi hai \(wo licensed hai\)\. Ye usse prerit apna checklist hai, iska koi validated cutoff nahi\./g,"Ye hamari apni checklist hai, iska koi validated cut-off nahi."],[/This is not the official SCQ \(it is licensed\)\. It is our own SCQ-inspired checklist with no validated cutoff\./g,"This is our own checklist with no validated cut-off."],[/\s*\(Altman\)/g,""],[/Y-BOCS|SCQ-inspired|SCQ|M-CHAT-R\/F|M-CHAT|PHQ-9|PHQ-A|PHQ-15|GAD-7|ASRM|MSI-BPD|OCI-R|DOCS|AQ-10|PCL-5|PQ-B|PSC-17|SPIN|SCARED|ASQ-style|ASQ style/g,"this screen"]];function i(y){return typeof y=="string"?(u.forEach(function(m){y=y.replace(m[0],m[1])}),y):Array.isArray(y)?y.map(i):y}Object.keys(MC.tests).forEach(function(y){var m=MC.tests[y];if(p[y]&&(m.name=[p[y],p[y]]),y==="phq15"&&(m.name=["Somatic symptoms (body complaints)","Somatic symptoms (body complaints)"]),r[y]&&(m.sub=r[y]),m.sub=i(m.sub),m.intro=i(m.intro),m.calc){var M=m.calc;m.calc=function(f){var K=M.call(m,f);return K.lines=i(K.lines),K.adv=i(K.adv),K.b=K.b&&K.b.map(i),K}}MC.names[y]=m.name[1]});function k(){["a","c"].forEach(function(y){MC.tabs[y].forEach(function(m){m.ids=m.ids.filter(function(M){return!g[M]})})}),MC.tabs.c=MC.tabs.c.filter(function(y){return y.ids.length})}k(),MC.tabs.a[3].ids.push("cptsd","grief","adj","diss"),MC.tabs.a.push({t:["Sharirik lakshan","Physical symptoms"],ids:["phq15"]});var c={},n=[];["a","c"].forEach(function(y){MC.tabs[y].forEach(function(m){var M=m.ids.filter(function(f){return c[f]?!1:(c[f]=1,!0)});M.length&&n.push({t:m.t,ids:M})})}),MC.groups=n})()}catch(a){setTimeout(function(){throw a})}